import { useEffect } from "react";

const HubspotForms = ({ portalId, formId, region, targetId }) => {
  useEffect(() => {
    // Function to load HubSpot script if not already loaded
    const loadHubSpotScript = () => {
      if (!document.querySelector('script[src*="js.hsforms.net"]')) {
        const script = document.createElement('script');
        script.src = '//js.hsforms.net/forms/embed/v2.js';
        script.async = true;
        document.head.appendChild(script);
      }
    };

    // Load the script first
    loadHubSpotScript();

    // Wait for hbspt to be available and create the form
    const interval = setInterval(() => {
      if (window.hbspt && window.hbspt.forms) {
        clearInterval(interval);
        
        // Clear any existing form in the target
        const targetElement = document.getElementById(targetId);
        if (targetElement) {
          targetElement.innerHTML = '';
        }
        
        window.hbspt.forms.create({
          portalId,
          formId,
          region,
          target: `#${targetId}`,
        });
      }
    }, 100);

    // Cleanup function
    return () => {
      clearInterval(interval);
      // Optional: Clear the form when component unmounts
      const targetElement = document.getElementById(targetId);
      if (targetElement) {
        targetElement.innerHTML = '';
      }
    };
  }, [portalId, formId, region, targetId]);

  return <div id={targetId}></div>;
};

export default HubspotForms;
